function actLineCheck() {
  var out = ['线路自检'];
  var best = '', bestMs = 1e9;
  for (var i = 0; i < HOSTS.length; i++) {
    var h = HOSTS[i], t0 = Date.now(), ok = false, ms = 0, note = '';
    try {
      var r = http.get(h + '/comic/all', { headers: hdr() });
      ms = Date.now() - t0;
      ok = !!(r && r.ok && r.status === 200 && /jm-card/.test(String(r.body || '')));
      note = ok ? ms + 'ms' : ('HTTP ' + (r && r.status));
    } catch (e) { ms = Date.now() - t0; note = '异常'; }
    out.push((ok ? '\u2713 ' : '\u2717 ') + h.replace(/^https?:\/\//, '') + '  ' + note);
    if (ok && ms < bestMs) { bestMs = ms; best = h; }
  }
  if (best) { try { vars.set('host', best); } catch (e) {} }
  out.push('\n当前线路：' + hostOf() + (best ? '（最快 ' + bestMs + 'ms）' : '（全部不通）'));
  return out.join('\n');
}

function actVideoCheck() {
